import{z as i,x as s,o as n,c as m,q as r,j as B,D as l,d as e,s as d,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"拉格朗日乘子","description":"","frontmatter":{"title":"拉格朗日乘子","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/lagrange-multiplier.md","filePath":"econ/lagrange-multiplier.md","lastUpdated":1791413859000}'),A={name:"econ/lagrange-multiplier.md"};function h(p,a,b,c,x,C){const t=s("Mermaid");return n(),m("div",null,[a[2]||(a[2]=r('<h1 id="拉格朗日乘子" tabindex="-1">拉格朗日乘子 <a class="header-anchor" href="#拉格朗日乘子" aria-label="Permalink to &quot;拉格朗日乘子&quot;">​</a></h1><div class="epigraph"><p>等式约束把可行方向压进切空间；乘子是目标梯度在约束法向的那一笔，使无约束一阶条件在增广函数上恢复。</p><footer>—— 据 Mas-Colell, Whinston and Green 数学附录；Boyd and Vandenberghe, Convex Optimization, 第 5 章整理</footer></div><p>上一课<a href="/econ/unconstrained-fonc">无约束一阶与二阶条件</a>在开集内令梯度为零。消费者花光预算、厂商的生产函数写成等式时，可行域是超曲面，沿约束法向走会立刻不可行。缺口不是再写 \\(\\nabla f=0\\)，而是：只对切空间里的方向要求一阶为零，法向差额用乘子吸收。不等式与互补松弛留给下一课 KKT。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\max_x f(x)\\) s.t. \\(h(x)=0\\)，其中 \\(h:U\\to\\mathbb{R}^k\\)，\\(k\\le n\\)。正则条件（约束梯度 \\(\\nabla h_j(x^*)\\) 线性无关，LICQ）下，存在 \\(\\lambda\\in\\mathbb{R}^k\\) 使 \\(\\nabla f(x^*)=\\sum_j\\lambda_j\\nabla h_j(x^*)\\)， 即 \\(\\nabla_x\\mathcal{L}(x^*,\\lambda)=0\\)，其中 \\(\\mathcal{L}(x,\\lambda)=f(x)-\\lambda\\cdot h(x)\\)（最小化时常写 \\(f+\\lambda\\cdot h\\)，符号约定要前后一致）。连同 \\(h(x^*)=0\\)，共 \\(n+k\\) 个方程。</p><p>预算等式 \\(p\\cdot x=w\\) 是 \\(k=1\\) 的仿射特例。\\(\\nabla u(x^*)=\\lambda p\\) 就是「边际替代率等于价格比」：乘子 \\(\\lambda\\) 是收入的影子价值。<span class="marginnote">用数字体会「影子价值」：若解出的 \\(\\lambda=0.5\\)，含义是——预算再松 1 元，最大效用大约再涨 0.5 个单位；松 100 元就涨约 50。所以 \\(\\lambda\\) 的单位是「每元钱换多少效用」，它给「钱」在效用尺度上定了价，这就是「影子价格」四个字的来历。</span>后课<a href="/econ/marshallian-demand">预算集与马歇尔需求</a>在局部非饱和下把不等式预算收成等式，用的正是这一课。本课不引入偏好公理，只把等式约束的一阶条件写清楚。</p><h3 id="乘子不是目标的权重" tabindex="-1">乘子不是目标的权重 <a class="header-anchor" href="#乘子不是目标的权重" aria-label="Permalink to &quot;乘子不是目标的权重&quot;">​</a></h3><p>\\(\\lambda\\) 不是「约束有多重要」的主观权重，而是一阶匹配的系数：它让目标梯度落在约束梯度张成的空间里。变一个单位约束（预算松一元），最优值变 \\(\\lambda\\)——这是<a href="/econ/envelope-theorem">包络定理</a>的话，本课只先承认 \\(\\lambda\\) 会出现在 \\(\\partial\\mathcal{L}/\\partial w\\) 里。把 \\(\\lambda\\) 理解成「随便乘的数」会丢掉影子价格。</p><p><span class="marginnote">LICQ 失败时乘子可以不存在或成一个仿射空间（如冗余约束）。经济学里线性预算在 \\(p\\neq 0\\) 时 LICQ 自动成立。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>构造 \\(\\mathcal{L}\\)，对 \\(x\\) 与 \\(\\lambda\\) 同时求驻点：\\(\\nabla_x\\mathcal{L}=0\\) 是一阶，\\(\\nabla_\\lambda\\mathcal{L}=-h=0\\) 把约束装回。二阶条件在切空间上：对一切满足 \\(Dh(x^*)v=0\\) 的 \\(v\\neq 0\\)，\\(v^\\top\\nabla_{xx}^2\\mathcal{L}\\,v\\) 取负（极大）。不是对所有 \\(v\\) 要求 Hessian 负定——沿法向的弯曲被约束禁掉了。<span class="marginnote">把约束面想成一根绷紧的铁丝：点只能在铁丝上滑动（切向），离开铁丝（法向）就不可行。二阶条件只问「沿铁丝滑过去，函数值会不会爬得更高」；至于离开铁丝的方向上函数怎么弯，与本题无关，所以 Hessian 不必全负定。初学者在这里最容易误判成「Hessian 必须整体负定」。</span></p><p>仿射约束加凹目标：一阶充分且全局。这是标准消费者问题最常用的一包假设。非线性等式 \\(h\\) 可能切出非凸可行集，一阶可以指向鞍点；那时 Lagrange 只是必要，不是充分。上一课上境图已经警告过：非线性等式毁掉凸。</p>',12)),(n(),B(o,null,{default:l(()=>[d(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E7%9B%AE%E6%A0%87%E6%A2%AF%E5%BA%A6%22%5D%20--%3E%20L%5B%22%E7%AD%89%E4%BA%8E%E7%BA%A6%E6%9D%9F%E6%A2%AF%E5%BA%A6%E7%9A%84%E7%BA%BF%E6%80%A7%E7%BB%84%E5%90%88%22%5D%0A%20%20H%5B%22%E7%AD%89%E5%BC%8F%20h(x)%3D0%22%5D%20--%3E%20T%5B%22%E5%8F%AF%E8%A1%8C%E6%96%B9%E5%90%91%E5%9C%A8%E5%88%87%E7%A9%BA%E9%97%B4%22%5D%0A%20%20T%20--%3E%20L%0A%20%20L%20--%3E%20LAM%5B%22%E4%B9%98%E5%AD%90%20lambda%20%E4%B8%BA%E7%B3%BB%E6%95%B0%22%5D%0A%20%20LAM%20--%3E%20ENV%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%8C%85%E7%BB%9C%E8%AF%BB%E5%87%BA%E5%BD%B1%E5%AD%90%E4%BB%B7%E6%A0%BC%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("在约束曲面上，允许的无穷小位移 \\(v\\) 满足 \\(Dh(x^*)v=0\\)。最优要求 \\(\\nabla f\\cdot v=0\\) 对一切这样的 \\(v\\)，故 \\(\\nabla f\\) 正交于切空间，即落在法空间里——法空间由 \\(\\nabla h_j\\) 张成。乘子就是这组坐标。"),E("span",{class:"marginnote"},"拿一道能口算的题走全程：\\(\\max\\,xy\\) s.t. \\(x+y=10\\)。令 \\(\\mathcal{L}=xy-\\lambda(x+y-10)\\)，一阶给 \\(\\lambda=y\\)、\\(\\lambda=x\\)，解得 \\(x=y=5\\)、\\(\\lambda=5\\)。把预算改成 \\(x+y=11\\)，最优值从 \\(25\\) 变成 \\(30.25\\)——每多 1 元预算效用约多 5，正是 \\(\\lambda\\)。全过程就是「构造 \\(\\mathcal{L}\\)、解一阶方程组、读 \\(\\lambda\\)」。")],-1)),(n(),B(o,null,{default:l(()=>[d(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%86%99%E4%B8%8B%E7%9B%AE%E6%A0%87%20f%20%E4%B8%8E%E7%AD%89%E5%BC%8F%E7%BA%A6%E6%9D%9F%20h%22%5D%20--%3E%20L%5B%22%E6%9E%84%E9%80%A0%E5%A2%9E%E5%B9%BF%E5%87%BD%E6%95%B0%20L%20%3D%20f%20%E2%88%92%20%CE%BB%C2%B7h%22%5D%0A%20%20L%20--%3E%20FOC%5B%22%E4%B8%80%E9%98%B6%EF%BC%9A%E2%88%87x%20L%20%3D%200%20%E4%B8%94%20h%20%3D%200%EF%BC%8C%E5%85%B1%20n%2Bk%20%E4%B8%AA%E6%96%B9%E7%A8%8B%22%5D%0A%20%20FOC%20--%3E%20SOL%5B%22%E8%A7%A3%E5%87%BA%E5%80%99%E9%80%89%E7%82%B9%E4%B8%8E%20%CE%BB%22%5D%0A%20%20SOL%20--%3E%20CHK%5B%22%E4%BA%8C%E9%98%B6%EF%BC%9A%E5%8F%AA%E5%9C%A8%E5%88%87%E7%A9%BA%E9%97%B4%E4%B8%8A%E5%AE%9A%E5%8F%B7%22%5D%0A%20%20CHK%20--%3E%20RD%5B%22%E8%A7%A3%E8%AF%BB%20%CE%BB%EF%BC%9A%E7%BA%A6%E6%9D%9F%E6%9D%BE%E4%B8%80%E5%8D%95%E4%BD%8D%EF%BC%8C%E6%9C%80%E4%BC%98%E5%80%BC%E5%8F%98%E5%A4%9A%E5%B0%91%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p>几何上这仍是分离：上优集与可行超曲面在切点分开，法向量分解成「目标的」与「约束的」。预算问题里两者共线，比例即 \\(\\lambda\\)。多种商品、一个预算，所以只有一个 \\(\\lambda\\)；多种资源约束就有一串乘子，后课规划问题、成本最小化会用到。</p><p><span class="marginnote">\\(\\lambda\\) 的符号取决于约束怎么写。\\(h=p\\cdot x-w\\) 与 \\(h=w-p\\cdot x\\) 差一个负号。读论文先看约束方向，再读「乘子为正」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不管不等式：\\(x\\ge 0\\)、产能上限、参与约束都是下一课。也不把 Lagrange 写成数值求解算法（增广 Lagrange、SQP）；主干要的是一阶刻画。不要在这里展开效用存在性：\\(\\nabla u=\\lambda p\\) 假定已经有可微的 \\(u\\)，那是微观主干后课。下一课把 \\(\\ge\\) 加进来，乘子变为 KKT 乘子并带互补松弛。</p><p>后课默认：等式约束内部解写成 \\(\\nabla_x\\mathcal{L}=0\\) 加上约束本身；线性预算下 \\(\\lambda\\) 是收入的边际价值候选。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>等式约束的一阶条件：目标梯度是约束梯度的线性组合。</li><li>乘子是法空间坐标，也是影子价格的候选。</li><li>二阶只在切空间上定号；仿射约束加凹目标则一阶全局充分。</li><li>LICQ 保证乘子存在；线性预算通常自动满足。</li><li>下一课：<a href="/econ/kkt-conditions">KKT 条件</a>。</li><li>出处：MWG 数学附录；Boyd and Vandenberghe 第 5 章。</li></ul>',7))])}const _=i(A,[["render",h]]);export{f as __pageData,_ as default};
